import { createSignal } from "solid-js";
import { render } from "solid-js/web";

import { InputEngineEvent } from "#core/ui/input/input-support.js";
import { InterfaceMode } from "#core/ui/interface-modes/interface-modes.js";
import Panel from "#core/ui/panel-support.js";

import { PauseMenu } from "#base/ui-next/screens/pause-menu/pause-menu.jsx";

export class ScreenPauseMenuBootstrap extends Panel {
	private dispose: (() => void) | null = null;

	onInitialize(): void {
		this.enableOpenSound = true;
		this.enableCloseSound = true;
		this.Root.setAttribute("data-audio-group-ref", "pause-menu");
	}

	onEngineInput(event: InputEngineEvent) {
		if (event.detail.status != InputActionStatuses.FINISH) {
			return;
		}

		if (event.detail.name === "sys-menu" || event.detail.name === "keyboard-escape") {
			InterfaceMode.switchToDefault();
		}
	}

	onAttach() {
		Input.setActiveContext(InputContext.Shell);
		super.onAttach();
		this.Root.classList.add("w-full", "h-full");
		this.dispose = render(() => {
			const [_ref, setRef] = createSignal<HTMLDivElement>();

			return PauseMenu({ ref: setRef });
		}, this.Root);
	}

	onDetach() {
		super.onDetach();

		if (this.dispose) {
			this.dispose();
			this.dispose = null;
		}
	}
}

Controls.define("screen-pause-menu-bootstrap", {
	createInstance: ScreenPauseMenuBootstrap,
	description: "Pause Menu",
});
